css:
:root {
  --brand: #c0392b;
  --cream: #fff8ef;
  --ink: #2b1d16;
  --space: 1rem;
  --radius: 12px;
}

body { font-family: system-ui, sans-serif; margin: 0; background: var(--cream); color: var(--ink); }
main, #site-footer { padding: 1rem; }
nav { display: flex; gap: 1rem; padding: 0.75rem; background: #2b1d16; }
nav a { color: #fff; }
.button { display: inline-block; color: #fff; padding: 0.5rem 1rem; text-decoration: none; background: var(--brand); border-radius: var(--radius); }
.dish { background: #fff; border-radius: 12px; overflow: hidden; }
.dish h3, .dish p { margin: 0.5rem; }
img { max-width: 100%; display: block; }
.favourites { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: var(--space); }
.dish img { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; }
